      await this.resourceSupervisor.recover(workerExit);
    } catch (error) {
      this.logger.record({
        kind: "failure",
        operation: "worker-replacement",
        failureCode: "controlled-resource",
        errorName: DaemonLogger.errorName(error),
      });
      throw error;
    }
  }
}

